from __future__ import annotations


TEMPLATE_PATH = 'backend/app/api/routes/customers.py'
TEMPLATE_CONTENT = 'from fastapi import APIRouter, Depends\nfrom sqlalchemy.ext.asyncio import AsyncSession\n\nfrom app.api.dependencies import get_current_user_id, require_role\nfrom app.core.database import get_db\nfrom app.schemas.customer import CustomerCreate, CustomerResponse\nfrom app.services.audit_service import create_audit_log\nfrom app.services.customer_service import create_customer, get_customers\n\n\nrouter = APIRouter()\n\n\n@router.get("/", response_model=list[CustomerResponse])\nasync def list_customers(\n    current_user_id: str = Depends(get_current_user_id),\n    _: bool = Depends(require_role(["owner", "admin", "member", "viewer"])),\n    db: AsyncSession = Depends(get_db),\n):\n    return await get_customers(db=db)\n\n\n@router.post("/", response_model=CustomerResponse)\nasync def add_customer(\n    payload: CustomerCreate,\n    current_user_id: str = Depends(get_current_user_id),\n    _: bool = Depends(require_role(["owner", "admin", "member"])),\n    db: AsyncSession = Depends(get_db),\n):\n    customer = await create_customer(db=db, payload=payload)\n\n    await create_audit_log(\n        db=db,\n        event_type="customer_created",\n        status="success",\n        actor_user_id=int(current_user_id),\n        route="/api/customers/",\n        detail=f"customer_id={customer.id}",\n    )\n\n    return customer\n'
